package io.github.finalparadox.client;
import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import io.github.finalparadox.entity.FrozenPrisonEntity;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.block.BlockRenderDispatcher;import net.minecraft.client.renderer.entity.*;import net.minecraft.client.renderer.texture.OverlayTexture;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.inventory.InventoryMenu;import net.minecraft.world.level.block.Blocks;
public final class FrozenPrisonRenderer extends EntityRenderer<FrozenPrisonEntity>{private final BlockRenderDispatcher blocks;public FrozenPrisonRenderer(EntityRendererProvider.Context c){super(c);blocks=c.getBlockRenderDispatcher();shadowRadius=0;}@Override public ResourceLocation getTextureLocation(FrozenPrisonEntity e){return InventoryMenu.BLOCK_ATLAS;}@Override public void render(FrozenPrisonEntity e,float y,float partial,PoseStack p,MultiBufferSource b,int light){for(int ring=0;ring<2;ring++)for(int i=0;i<4;i++){double a=i*Math.PI/2+ring*Math.PI/4;p.pushPose();p.translate(Math.cos(a)*.55,ring*.75,Math.sin(a)*.55);p.mulPose(Axis.YP.rotationDegrees((float)-Math.toDegrees(a)));p.mulPose(Axis.ZP.rotationDegrees(45));p.scale(.65F,.65F,.65F);p.translate(-.5,-.5,-.5);blocks.renderSingleBlock(Blocks.ICE.defaultBlockState(),p,b,light,OverlayTexture.NO_OVERLAY);p.popPose();}super.render(e,y,partial,p,b,light);}}
